    await page.goto('/');

    await expect(page.getByTestId('person-row-1').getByTestId('concept-ballast')).toHaveText('591');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-ballast')).toHaveText('525');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-ballast')).toHaveText('872');
    await expect(page.getByTestId('person-row-4').getByTestId('concept-ballast')).toHaveText('354');
    await expect(page.getByTestId('person-row-5').getByTestId('concept-ballast')).toHaveText('152');
    await expect(page.getByTestId('person-row-6').getByTestId('concept-ballast')).toHaveText('266');
    await expect(page.getByTestId('person-row-9').getByTestId('concept-ballast')).toHaveText('481');
  });
});
